/**
 * The small half of the baked dataset — safe to import from anywhere.
 *
 * index.json holds the stroller list the search boxes filter and the comparison
 * pages the build generates. Full specs live in ./specs, which is an order of
 * magnitude bigger and must not be imported from client code; see the note
 * there.
 *
 * Both files are generated by scripts/build-dataset.mjs straight from Postgres
 * and committed, so a build needs no database and the browser makes no API
 * calls. Publishing a change is: run the script, commit, push.
 */
import type { StrollerSummary } from "../features/strollers/paths";
import index from "./index.json";

export type ComparisonPage = {
  slug: string;
  title: string;
  strollerIds: number[];
  /** Listed under "New comparisons" on the home page rather than "More". */
  isNew: boolean;
};

const data = index as {
  generatedAt: string;
  strollers: StrollerSummary[];
  comparisons: ComparisonPage[];
};

/** The light shape the search boxes and link builders need. */
export const STROLLER_SUMMARIES: StrollerSummary[] = data.strollers;

/** Every comparison page the site has, in the order the DB gave them. */
export const COMPARISON_PAGES: ComparisonPage[] = data.comparisons;
